"use client";

import {
  type ButtonHTMLAttributes,
  createContext,
  type HTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
  use,
  useCallback,
  useId,
  useRef,
  useState,
} from "react";
import { useIndicator } from "../interaction/hooks";
import { cx } from "../utils/cx";

type TabsContextValue = {
  value: string;
  select: (value: string) => void;
  idFor: (value: string, part: "tab" | "panel") => string;
  orientation: "horizontal" | "vertical";
};
const TabsContext = createContext<TabsContextValue | null>(null);

function useTabs(part: string): TabsContextValue {
  const ctx = use(TabsContext);
  if (!ctx) throw new Error(`<${part}> must be inside <Tabs>`);
  return ctx;
}

export type TabsProps = Omit<HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> & {
  /** Controlled selected value. */
  value?: string;
  /** Uncontrolled initial value. */
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  orientation?: "horizontal" | "vertical";
  children: ReactNode;
};

/**
 * Tabs that switch panels in place (a gallery workspace: Photos, Design, Share). ARIA tablist with roving focus:
 * arrows move and select, Home/End jump. For links between pages use PageTabs.
 */
export function Tabs({
  value: controlled,
  defaultValue = "",
  onValueChange,
  orientation = "horizontal",
  className,
  children,
  ...rest
}: TabsProps) {
  const [uncontrolled, setUncontrolled] = useState(defaultValue);
  const value = controlled ?? uncontrolled;
  const base = useId();
  const select = useCallback(
    (v: string) => {
      if (controlled === undefined) setUncontrolled(v);
      onValueChange?.(v);
    },
    [controlled, onValueChange],
  );
  const idFor = useCallback((v: string, part: "tab" | "panel") => `${base}-${part}-${v}`, [base]);
  return (
    <TabsContext value={{ value, select, idFor, orientation }}>
      <div {...rest} className={cx("hm-tabs", className)} data-orientation={orientation}>
        {children}
      </div>
    </TabsContext>
  );
}

export type TabListProps = HTMLAttributes<HTMLDivElement> & {
  "aria-label": string;
  /** `underline`: text tabs on a hairline (default). `pill`: quiet pills, for short filter-like sets. */
  variant?: "underline" | "pill";
};

export function TabList({ variant = "underline", className, onKeyDown, ...rest }: TabListProps) {
  const { orientation, value } = useTabs("TabList");
  const ref = useRef<HTMLDivElement>(null);
  useIndicator(ref, { item: '[role="tab"]', active: '[role="tab"][aria-selected="true"]' });
  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(e);
    if (e.defaultPrevented) return;
    const next = orientation === "vertical" ? "ArrowDown" : "ArrowRight";
    const prev = orientation === "vertical" ? "ArrowUp" : "ArrowLeft";
    if (![next, prev, "Home", "End"].includes(e.key)) return;
    const tabs = Array.from(e.currentTarget.querySelectorAll<HTMLButtonElement>('[role="tab"]:not(:disabled)'));
    const i = tabs.indexOf(document.activeElement as HTMLButtonElement);
    const n = tabs.length;
    if (!n) return;
    const to = e.key === "Home" ? 0 : e.key === "End" ? n - 1 : e.key === next ? (i + 1) % n : (i - 1 + n) % n;
    e.preventDefault();
    tabs[to]?.focus();
    tabs[to]?.click();
  };
  return (
    <div
      {...rest}
      ref={ref}
      role="tablist"
      aria-orientation={orientation}
      className={cx("hm-tab-list", className)}
      data-variant={variant}
      onKeyDown={onKey}
    />
  );
}

export type TabProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "value"> & { value: string };

export function Tab({ value, className, onClick, ...rest }: TabProps) {
  const ctx = useTabs("Tab");
  const selected = ctx.value === value;
  return (
    <button
      {...rest}
      type="button"
      role="tab"
      id={ctx.idFor(value, "tab")}
      aria-selected={selected}
      aria-controls={ctx.idFor(value, "panel")}
      tabIndex={selected ? 0 : -1}
      className={cx("hm-tab", className)}
      onClick={(e) => {
        onClick?.(e);
        if (!e.defaultPrevented) ctx.select(value);
      }}
    />
  );
}

export type TabPanelProps = HTMLAttributes<HTMLDivElement> & {
  value: string;
  /** Keep the panel mounted (hidden) when not selected, preserving its state. */
  keepMounted?: boolean;
};

export function TabPanel({ value, keepMounted, className, children, ...rest }: TabPanelProps) {
  const ctx = useTabs("TabPanel");
  const selected = ctx.value === value;
  if (!selected && !keepMounted) return null;
  return (
    <div
      {...rest}
      role="tabpanel"
      id={ctx.idFor(value, "panel")}
      aria-labelledby={ctx.idFor(value, "tab")}
      hidden={!selected}
      tabIndex={0}
      className={cx("hm-tab-panel", className)}
    >
      {children}
    </div>
  );
}
